package warranty

import (
	"fmt"
	"sync"
	"time"
)

// Product 是登记的产品保修信息。
type Product struct {
	// ID 是唯一产品编号。
	ID string
	// PurchaseTime 是购买时刻。
	PurchaseTime time.Time
	// WarrantyDays 是保修天数，必须为正整数；保修期自购买时刻起，每天按二十四小时计算。
	WarrantyDays int
	// ExcludedCodes 是除外故障代码集合；命中代码的请求一律拒绝。
	ExcludedCodes map[string]struct{}
}

// Part 是登记的备件及其库存。
type Part struct {
	// ID 是唯一备件编号。
	ID string
	// Stock 是当前剩余实物库存，被成功使用的承诺分批扣减。
	Stock int
}

// Request 是提交的保修请求，指定产品和故障代码。
type Request struct {
	// ID 是唯一请求编号。
	ID string
	// ProductID 是关联的产品编号。
	ProductID string
	// FaultCode 是故障代码，不能为空。
	FaultCode string
}

// CommitmentStatus 是承诺的当前状态。
type CommitmentStatus string

const (
	// CommitmentActive 表示承诺有效：未取消且未到期。
	CommitmentActive CommitmentStatus = "active"
	// CommitmentCanceled 表示承诺已被取消。
	CommitmentCanceled CommitmentStatus = "canceled"
	// CommitmentExpired 表示承诺已到期，余量自动释放。
	CommitmentExpired CommitmentStatus = "expired"
)

// Commitment 是一笔备件承诺。
type Commitment struct {
	// ID 是全局唯一的提交编号。
	ID string
	// RequestID 是关联的请求编号。
	RequestID string
	// PartID 是预留的备件编号。
	PartID string
	// Quantity 是原定承诺数量（正整数）。
	Quantity int
	// Used 是已成功使用的累计数量。
	Used int
	// Expiry 是到期时刻；当前时刻等于或晚于它时承诺到期，余量释放。
	Expiry time.Time
	// Canceled 表示是否已被取消。
	Canceled bool
	// Expired 表示到期是否已被确认。到期确认是不可逆的结果：一经确认，
	// 未用占用永久释放，之后即使传入更早的当前时刻也仍视为到期，不能重新
	// 占用已释放给其他请求的数量。未确认前仅在当次时刻达到到期时刻时
	// （库存查询、请求查询、新预留核算、新使用判断）就本次涉及的承诺确认。
	// 幂等重试、参数非法或引用对象不存在而提前失败的调用不确认到期。
	Expired bool
}

// Unused 返回未用数量。
func (c *Commitment) Unused() int { return c.Quantity - c.Used }

// confirmExpiryLocked 在已持锁的情况下按本次当前时刻确认单笔承诺到期。
// 仅确认本次操作涉及的承诺：未取消、尚未确认且当前时刻已达到到期时刻时
// 置位 Expired；该结果不可逆。已取消的承诺保持 canceled，不确认到期。
func (s *Store) confirmExpiryLocked(c *Commitment, now time.Time) {
	if c.Canceled || c.Expired {
		return
	}
	if !now.Before(c.Expiry) {
		c.Expired = true
	}
}

// confirmExpiriesLocked 确认全部满足 match 的承诺中已到期但尚未确认的记录。
// 只确认本次操作涉及的承诺，不触碰其他对象的记录。
func (s *Store) confirmExpiriesLocked(match func(*Commitment) bool, now time.Time) {
	for _, c := range s.commitments {
		if match(c) {
			s.confirmExpiryLocked(c, now)
		}
	}
}

// confirmPartExpiriesLocked 确认指定备件下全部已到期但尚未确认的承诺。
func (s *Store) confirmPartExpiriesLocked(partID string, now time.Time) {
	s.confirmExpiriesLocked(func(c *Commitment) bool { return c.PartID == partID }, now)
}

// confirmRequestExpiriesLocked 确认指定请求下全部已到期但尚未确认的承诺。
func (s *Store) confirmRequestExpiriesLocked(requestID string, now time.Time) {
	s.confirmExpiriesLocked(func(c *Commitment) bool { return c.RequestID == requestID }, now)
}

// Status 返回承诺的当前状态。
// 已确认到期不可逆：即使传入更早的当前时刻也显示 expired；状态不要求
// 调用时刻递增。取消优先于到期，已取消的记录始终显示 canceled。
func (c *Commitment) Status(now time.Time) CommitmentStatus {
	switch {
	case c.Canceled:
		return CommitmentCanceled
	case c.Expired:
		return CommitmentExpired
	case !now.Before(c.Expiry):
		return CommitmentExpired
	default:
		return CommitmentActive
	}
}

// Usage 是一次成功的承诺使用记录。
type Usage struct {
	// ID 是全局唯一的使用编号。
	ID string
	// CommitmentID 是被扣减的承诺编号。
	CommitmentID string
	// Quantity 是本次使用的正整数数量。
	Quantity int
}

// Store 保存全部登记信息与承诺。所有方法均为并发安全。
type Store struct {
	mu          sync.Mutex
	products    map[string]*Product
	parts       map[string]*Part
	requests    map[string]*Request
	commitments map[string]*Commitment
	usages      map[string]*Usage
	// firstResults 保存每个承诺编号首次预留成功时返回的承诺快照（已用数量为零、
	// 未取消）。原样重试取回它，不随分批使用、取消或到期改变。
	firstResults map[string]Commitment
	// history 保存按请求分组的预留处理历史，仅存在于当前仓库实例中。
	history map[string][]HistoryRecord
}

// NewStore 创建一个空的保修备件仓库。
func NewStore() *Store {
	return &Store{
		products:     make(map[string]*Product),
		parts:        make(map[string]*Part),
		requests:     make(map[string]*Request),
		commitments:  make(map[string]*Commitment),
		usages:       make(map[string]*Usage),
		firstResults: make(map[string]Commitment),
		history:      make(map[string][]HistoryRecord),
	}
}

// RegisterProduct 登记产品：购买时刻、保修天数和除外故障代码。
// 编号重复时返回 ErrDuplicateID 且保留原记录；已存在的非空编号优先于其他
// 参数校验，即使新提交的保修天数、截止时刻或除外清单不合法也报编号重复，
// 原记录不被覆盖、清空或部分替换。保修天数必须为正整数，且自购买时刻起完整
// 天数（每天二十四小时）的截止时刻必须落在时间类型的可表示范围内，否则返回
// ErrInvalidParam，不保存产品记录。
func (s *Store) RegisterProduct(id string, purchaseTime time.Time, warrantyDays int, excludedCodes []string) error {
	if id == "" {
		return fmt.Errorf("%w: product id must not be empty", ErrInvalidParam)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	// 编号已存在时一律报重复并保留原记录，不再校验新提交的条款。
	if _, ok := s.products[id]; ok {
		return fmt.Errorf("%w: product %q", ErrDuplicateID, id)
	}
	if warrantyDays <= 0 {
		return fmt.Errorf("%w: warranty days must be a positive integer", ErrInvalidParam)
	}
	// 截止时刻超出时间类型可表示范围的期限无法登记，不保存产品记录；
	// 之后以同一编号提交可表示的条款仍可正常登记。
	if _, ok := warrantyExpiry(purchaseTime, warrantyDays); !ok {
		return fmt.Errorf("%w: warranty expiry for %d days is not representable", ErrInvalidParam, warrantyDays)
	}
	codes := make(map[string]struct{}, len(excludedCodes))
	for _, c := range excludedCodes {
		if c == "" {
			return fmt.Errorf("%w: excluded fault code must not be empty", ErrInvalidParam)
		}
		codes[c] = struct{}{}
	}
	s.products[id] = &Product{
		ID:            id,
		PurchaseTime:  purchaseTime,
		WarrantyDays:  warrantyDays,
		ExcludedCodes: codes,
	}
	return nil
}

// RegisterPart 登记备件及其非负整数初始库存。
// 编号重复时返回 ErrDuplicateID 且保留原记录：已存在的非空编号优先于本次
// 库存校验，即使再次提交的初始库存为负数或零，也一律报编号重复，重复登记
// 既不是补货也不会重置剩余库存，原备件的实物库存与承诺占用均保持不变。
// 未登记过的非空编号首次提交时，初始库存必须是非负整数，否则返回
// ErrInvalidParam，不保存备件记录、不占用编号；零库存也是有效登记。
func (s *Store) RegisterPart(id string, initialStock int) error {
	if id == "" {
		return fmt.Errorf("%w: part id must not be empty", ErrInvalidParam)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	// 编号已存在时一律报重复并保留原记录，不再校验本次提交的初始库存。
	if _, ok := s.parts[id]; ok {
		return fmt.Errorf("%w: part %q", ErrDuplicateID, id)
	}
	if initialStock < 0 {
		return fmt.Errorf("%w: initial stock must be a non-negative integer", ErrInvalidParam)
	}
	s.parts[id] = &Part{ID: id, Stock: initialStock}
	return nil
}

// SubmitRequest 提交保修请求，指定产品和故障代码。
// 编号重复时返回 ErrDuplicateID 且保留原记录：已存在的非空编号优先于本次
// 参数校验，即使再次提交换了产品编号，或把故障代码改成空串等不合法内容，
// 也一律报编号重复，原请求的产品编号与故障代码不被覆盖、清空或部分替换，
// 资格依据、关联承诺与预留历史都继续按第一次成功提交的资料执行。
// 空请求编号或空故障代码的首次提交返回 ErrInvalidParam，不保存请求记录；
// 提交时不校验产品是否已登记，产品缺失留待资格查询与预留时报告。
func (s *Store) SubmitRequest(id, productID, faultCode string) error {
	if id == "" {
		return fmt.Errorf("%w: request id must not be empty", ErrInvalidParam)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	// 编号已存在时一律报重复并保留原记录，不再校验新提交的产品与故障代码。
	if _, ok := s.requests[id]; ok {
		return fmt.Errorf("%w: request %q", ErrDuplicateID, id)
	}
	if faultCode == "" {
		return fmt.Errorf("%w: fault code must not be empty", ErrInvalidParam)
	}
	s.requests[id] = &Request{ID: id, ProductID: productID, FaultCode: faultCode}
	return nil
}

// Product 返回指定编号的产品副本，不存在时返回 ErrNotFound。
func (s *Store) Product(id string) (Product, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	p, ok := s.products[id]
	if !ok {
		return Product{}, fmt.Errorf("%w: product %q", ErrNotFound, id)
	}
	cp := *p
	cp.ExcludedCodes = make(map[string]struct{}, len(p.ExcludedCodes))
	for k := range p.ExcludedCodes {
		cp.ExcludedCodes[k] = struct{}{}
	}
	return cp, nil
}

// Part 返回指定编号的备件副本，不存在时返回 ErrNotFound。
func (s *Store) Part(id string) (Part, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	p, ok := s.parts[id]
	if !ok {
		return Part{}, fmt.Errorf("%w: part %q", ErrNotFound, id)
	}
	return *p, nil
}

// Request 返回指定编号的请求副本，不存在时返回 ErrNotFound。
func (s *Store) Request(id string) (Request, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	r, ok := s.requests[id]
	if !ok {
		return Request{}, fmt.Errorf("%w: request %q", ErrNotFound, id)
	}
	return *r, nil
}

// Commitment 返回指定编号的承诺副本，不存在时返回 ErrNotFound。
func (s *Store) Commitment(id string) (Commitment, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.commitments[id]
	if !ok {
		return Commitment{}, fmt.Errorf("%w: commitment %q", ErrNotFound, id)
	}
	return *c, nil
}

package warranty

import (
	"fmt"
	"math"
	"time"
)

// unixEpochToInternal 是 Unix 秒与 time.Time 内部绝对秒之间的固定偏移
// （公元 1 年 1 月 1 日到 1970 年 1 月 1 日的秒数）。
const unixEpochToInternal = 62135596800

// secondsPerDay 是每天的秒数；保修期每天固定二十四小时，与时区无关。
const secondsPerDay = 24 * 60 * 60

// warrantyExpiry 计算保修截止时刻：自购买时刻起完整 days 个二十四小时。
// 不经过 time.Duration（其上限约 106751 天），较长保修期限不会溢出回绕；
// 秒以下精度与购买时刻的时区表示原样保留。days 为正整数但截止时刻超出
// 时间类型的可表示范围时返回 ok=false。
func warrantyExpiry(purchase time.Time, days int) (expiry time.Time, ok bool) {
	d := int64(days)
	if d <= 0 || d > math.MaxInt64/secondsPerDay {
		return time.Time{}, false
	}
	add := d * secondsPerDay
	unix := purchase.Unix()
	// 可表示的最大 Unix 秒为 math.MaxInt64 - unixEpochToInternal；
	// 写成 unix > max-add 避免任何中间量溢出。
	if unix > math.MaxInt64-unixEpochToInternal-add {
		return time.Time{}, false
	}
	return time.Unix(unix+add, int64(purchase.Nanosecond())).In(purchase.Location()), true
}

// RejectionReason 是资格拒绝原因。
type RejectionReason string

const (
	// ReasonPurchaseInFuture 表示购买时刻晚于当前时刻。
	ReasonPurchaseInFuture RejectionReason = "purchase_time_in_future"
	// ReasonWarrantyExpired 表示当前时刻已达到或超过保修截止时刻。
	ReasonWarrantyExpired RejectionReason = "warranty_expired"
	// ReasonFaultExcluded 表示故障代码在除外清单中。
	ReasonFaultExcluded RejectionReason = "fault_code_excluded"
)

// Eligibility 是按请求查询的资格依据与拒绝原因。
type Eligibility struct {
	// RequestID 是请求编号。
	RequestID string
	// ProductID 是产品编号。
	ProductID string
	// FaultCode 是故障代码。
	FaultCode string
	// Eligible 表示在当次时刻是否合格。
	Eligible bool
	// Reasons 列出全部拒绝原因；过保与除外同时成立时会列出两项。
	Reasons []RejectionReason
	// PurchaseTime 是购买时刻（资格依据）。
	PurchaseTime time.Time
	// WarrantyDays 是保修天数（资格依据）。
	WarrantyDays int
	// WarrantyExpiry 是保修截止时刻，自购买时刻起按每天二十四小时计算；
	// 当前时刻达到该时刻即算过保。
	WarrantyExpiry time.Time
	// Excluded 表示故障代码是否命中除外清单。
	Excluded bool
}

// evaluateLocked 在已持锁的情况下计算请求在当前时刻的资格。
// 未知产品返回 ErrNotFound，缺少故障代码返回 ErrInvalidParam。
func (s *Store) evaluateLocked(req *Request, now time.Time) (*Eligibility, error) {
	prod, ok := s.products[req.ProductID]
	if !ok {
		return nil, fmt.Errorf("%w: product %q", ErrNotFound, req.ProductID)
	}
	if req.FaultCode == "" {
		return nil, fmt.Errorf("%w: fault code must not be empty", ErrInvalidParam)
	}
	// 登记时已校验截止时刻可表示，这里一定成功。
	expiry, _ := warrantyExpiry(prod.PurchaseTime, prod.WarrantyDays)
	e := &Eligibility{
		RequestID:      req.ID,
		ProductID:      prod.ID,
		FaultCode:      req.FaultCode,
		PurchaseTime:   prod.PurchaseTime,
		WarrantyDays:   prod.WarrantyDays,
		WarrantyExpiry: expiry,
	}
	if prod.PurchaseTime.After(now) {
		e.Reasons = append(e.Reasons, ReasonPurchaseInFuture)
	}
	if !now.Before(e.WarrantyExpiry) {
		e.Reasons = append(e.Reasons, ReasonWarrantyExpired)
	}
	if _, excluded := prod.ExcludedCodes[req.FaultCode]; excluded {
		e.Excluded = true
		e.Reasons = append(e.Reasons, ReasonFaultExcluded)
	}
	e.Eligible = len(e.Reasons) == 0
	return e, nil
}

// Evaluate 返回指定请求在当前时刻的资格依据与拒绝原因。
// 未知产品或缺少故障代码时明确失败，不产生任何承诺。
func (s *Store) Evaluate(requestID string, now time.Time) (*Eligibility, error) {
	if requestID == "" {
		return nil, fmt.Errorf("%w: request id must not be empty", ErrInvalidParam)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	req, ok := s.requests[requestID]
	if !ok {
		return nil, fmt.Errorf("%w: request %q", ErrNotFound, requestID)
	}
	return s.evaluateLocked(req, now)
}

package warranty

import (
	"fmt"
	"time"
)

// HistoryError 是预留提交失败的具体错误类别。
type HistoryError string

const (
	// HistoryErrorInvalidParam 表示入参不合法（如非正数量、到期时刻未晚于当前时刻）。
	HistoryErrorInvalidParam HistoryError = "invalid_param"
	// HistoryErrorConflict 表示提交编号被重复用于不同内容。
	HistoryErrorConflict HistoryError = "conflict"
	// HistoryErrorProductNotFound 表示请求关联的产品尚未登记，资格依据为空。
	HistoryErrorProductNotFound HistoryError = "product_not_found"
	// HistoryErrorPartNotFound 表示预留的备件尚未登记，库存依据为空。
	HistoryErrorPartNotFound HistoryError = "part_not_found"
	// HistoryErrorIneligible 表示请求在当次时刻不满足保修资格。
	HistoryErrorIneligible HistoryError = "ineligible"
	// HistoryErrorInsufficientStock 表示可承诺数量不足。
	HistoryErrorInsufficientStock HistoryError = "insufficient_stock"
)

// StockBasis 是提交处理前的库存依据快照。
type StockBasis struct {
	// PhysicalRemaining 是本次提交处理前的剩余实物库存。
	PhysicalRemaining int
	// ActiveOccupied 是本次提交处理前的有效承诺未用总量。
	ActiveOccupied int
	// Committable 是本次提交处理前的可承诺数量（实物剩余扣除有效占用）。
	Committable int
}

// HistoryRecord 是一次预留提交的处理历史记录。
// 每次首次预留成功及每次失败提交都会留下一条记录；同编号同内容的幂等重试不追加。
type HistoryRecord struct {
	// Seq 是记录在所属请求内的处理次序号，按处理次序严格递增。
	Seq int
	// CommitID 是本次提交的承诺编号。
	CommitID string
	// PartID 是本次提交预留的备件编号。
	PartID string
	// Quantity 是本次提交的数量。
	Quantity int
	// Expiry 是本次提交的到期时刻。
	Expiry time.Time
	// Now 是调用方本次提交给定的当前时刻。
	Now time.Time
	// Success 表示本次提交是否成功。
	Success bool
	// Error 是失败的具体错误类别；成功时为空。
	Error HistoryError
	// Eligibility 是资格依据快照；产品缺失等情况下明确为空（nil），不用合格替代缺失。
	Eligibility *Eligibility
	// StockBasis 是库存依据快照；备件缺失等情况下明确为空（nil），不用零库存替代缺失。
	StockBasis *StockBasis
}

// cloneEligibility 返回资格依据快照的深拷贝（含拒绝原因列表）。
func cloneEligibility(e *Eligibility) *Eligibility {
	if e == nil {
		return nil
	}
	cp := *e
	if len(e.Reasons) > 0 {
		cp.Reasons = append(make([]RejectionReason, 0, len(e.Reasons)), e.Reasons...)
	}
	return &cp
}

// cloneStockBasis 返回库存依据快照的深拷贝。
func cloneStockBasis(b *StockBasis) *StockBasis {
	if b == nil {
		return nil
	}
	cp := *b
	return &cp
}

// appendHistoryLocked 在已持锁的情况下追加一条处理记录。
// 序号按处理次序严格递增；提交时刻相同或前后颠倒都不改变这个次序。
func (s *Store) appendHistoryLocked(requestID string, rec HistoryRecord) {
	rec.Seq = len(s.history[requestID]) + 1
	s.history[requestID] = append(s.history[requestID], rec)
}

// recordReserveLocked 在已持锁的情况下，仅当请求已知时为一次预留提交追加一条
// 处理记录。请求编号为空或尚未登记时不创建请求和历史；记录内容（成功标记或
// 失败类别、资格与库存依据快照）由调用方按当次处理结果给定，这里不补全或改写。
func (s *Store) recordReserveLocked(requestID string, rec HistoryRecord) {
	if _, ok := s.requests[requestID]; !ok {
		return
	}
	s.appendHistoryLocked(requestID, rec)
}

// RequestHistory 返回指定请求的预留处理历史，按处理次序排列，序号严格递增。
// 历史查询不需要提供当前时刻；已知请求没有记录时返回空列表。
// 返回的列表及记录均为副本，调用方修改不会影响已保存的历史与后续查询。
func (s *Store) RequestHistory(requestID string) ([]HistoryRecord, error) {
	if requestID == "" {
		return nil, fmt.Errorf("%w: request id must not be empty", ErrInvalidParam)
	}
	s.mu.Lock()
	defer s.mu.Unlock()

	if _, ok := s.requests[requestID]; !ok {
		return nil, fmt.Errorf("%w: request %q", ErrNotFound, requestID)
	}
	src := s.history[requestID]
	out := make([]HistoryRecord, len(src))
	for i, rec := range src {
		cp := rec
		cp.Eligibility = cloneEligibility(rec.Eligibility)
		cp.StockBasis = cloneStockBasis(rec.StockBasis)
		out[i] = cp
	}
	return out, nil
}

package warranty

import (
	"fmt"
	"time"
)

// stockAccountLocked 按统一的库存规则核算指定备件当前的账目：实物剩余只扣除
// 成功使用的数量（即备件当前库存），有效占用是该备件所有未取消、未确认到期
// 承诺的未用总量，可承诺数量等于实物剩余减去有效占用。已取消或已确认到期的
// 承诺不计入占用；到期一经确认不可逆，与本次传入的当前时刻无关，因此这里
// 不接收当前时刻，时刻相关的到期确认由调用方在核算前对本次涉及的承诺显式
// 完成。新预留的库存核算与按备件的库存查询共用这一份账目，同一条库存规则
// 不再分别维护。
//
// 调用方须已确认备件存在。
func (s *Store) stockAccountLocked(partID string) StockBasis {
	account := StockBasis{PhysicalRemaining: s.parts[partID].Stock}
	for _, c := range s.commitments {
		if c.PartID != partID {
			continue
		}
		if c.Canceled || c.Expired {
			continue
		}
		account.ActiveOccupied += c.Unused()
	}
	account.Committable = account.PhysicalRemaining - account.ActiveOccupied
	return account
}

// Reserve 为请求预留一种备件，数量为正整数，到期时刻必须晚于本次提交的当前时刻。
// 每次首次预留都按当次时刻重新判断资格；可承诺数量等于剩余实物库存扣除所有
// 有效承诺的未用数量。库存不足、未知请求或备件、不合格请求都不占用数量。
//
// 新预留的库存核算会先按本次当前时刻确认该备件下已到期的承诺：当前时刻达到
// 其到期时刻的未取消承诺被永久标记到期，只释放未用占用、不增加实物库存；该
// 结果不可逆，之后即使传入更早时刻核算也不再计算其未用数量，不能再次占用已
// 释放给其他请求的数量。空编号、非正数量等参数非法，或请求、备件（含资格所
// 需产品）不存在而提前失败的调用，不用本次时刻确认任何承诺。
//
// 提交编号全局唯一。已成功的编号：
//   - 原样重试（请求编号、备件编号、数量和到期时刻一致；当前时刻不属于提交内容，
//     到期时刻按实际时刻比较，换时区表示仍算一致）只取回首次预留成功的完整承诺，
//     其中已用数量仍为零、取消标记仍为否，不重新判断资格与库存，不重复占用，不
//     追加历史，也不恢复已释放占用或补回已扣减的实物库存；无论请求后来过保、库存
//     不足，还是承诺已分批使用、全部使用、取消或到期，即使本次当前时刻等于或晚于
//     原到期时刻，均如此。
//   - 改请求、备件、数量或到期时刻任一项即返回 ErrConflict，即使新参数本身非法
//     （空请求、未知备件、零数量、已过去的到期时刻）也按编号冲突处理；失败记录挂在
//     本次提交指定的已知请求下，请求为空或不存在时不创建请求和历史。
//
// 首次成功与编号绑定在同一临界区内原子完成：同一个尚未成功预留的编号被两组不同
// 内容（请求、备件、数量或到期时刻不同）并发抢占，且每组内容都可能同时提交多次
// 时，只能有一份内容成为首次承诺——与其完全相同的并发提交全部成功并返回同一份
// 完整首次承诺（已用数量为零、未取消），另一组全部返回 ErrConflict，不能两笔都
// 成功，也不会把后来的内容写进已经成功的承诺；即使库存充足到能同时容纳两笔数量，
// 有效占用也只对应获胜数量（预留不扣减实物库存），承诺只归获胜请求。库存恰好被
// 首次成功预留用完时，同内容的其余并发提交仍取回首次结果而不是 ErrInsufficientStock，
// 另一组仍报编号冲突；赛后按胜出内容重试取回首次承诺，按落败内容重试仍冲突，库存
// 与归属保持原结果。获胜请求只留一条首次成功记录（保存当次资格与新增占用前的库存
// 依据），相同内容的其余成功返回不追加；落败请求的每次提交各留一条冲突失败记录，
// 保留当次数量、到期时刻与当前时刻，资格与库存依据均为空，记录不挂到获胜请求下。
//
// 尚未成功占用的编号继续按本次参数、资格和库存判断；失败记录照常保留，失败后允许
// 用该编号再次提交。每次首次预留成功及每次失败提交都会在对应请求下留下记录。
func (s *Store) Reserve(commitID, requestID, partID string, quantity int, expiry, now time.Time) (Commitment, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	// 本次提交的历史记录骨架：承诺编号、备件、数量、到期时刻与当前时刻在各分支
	// 一致，统一在这里填写，各分支不再重复。record 按统一规则留痕：成功标记与
	// 失败类别互斥，资格与库存依据快照原样保存（提前失败时为 nil，不用合格资格
	// 或零库存替代缺失）；请求为空或尚未登记时不创建请求和历史。
	base := HistoryRecord{
		CommitID: commitID,
		PartID:   partID,
		Quantity: quantity,
		Expiry:   expiry,
		Now:      now,
	}
	record := func(success bool, herr HistoryError, elig *Eligibility, basis *StockBasis) {
		rec := base
		rec.Success = success
		rec.Error = herr
		rec.Eligibility = cloneEligibility(elig)
		rec.StockBasis = basis
		s.recordReserveLocked(requestID, rec)
	}

	// 已成功的编号优先按重复提交处理，优先于本次参数校验：原样重试不因本次当前
	// 时刻晚于到期时刻等参数问题失败；改内容则一律冲突。
	if first, ok := s.firstResults[commitID]; ok {
		if first.RequestID != requestID || first.PartID != partID ||
			first.Quantity != quantity || !first.Expiry.Equal(expiry) {
			// 冲突：在本次提交指定的已知请求下记录失败，不挂到原承诺所属请求。
			record(false, HistoryErrorConflict, nil, nil)
			return Commitment{}, fmt.Errorf("%w: commit id %q reused with different content", ErrConflict, commitID)
		}
		// 原样重试：返回首次成功时的承诺快照，不反映后来的使用、取消或到期。
		return first, nil
	}

	if commitID == "" || requestID == "" || partID == "" {
		record(false, HistoryErrorInvalidParam, nil, nil)
		return Commitment{}, fmt.Errorf("%w: commit/request/part id must not be empty", ErrInvalidParam)
	}
	if quantity <= 0 {
		record(false, HistoryErrorInvalidParam, nil, nil)
		return Commitment{}, fmt.Errorf("%w: reserve quantity must be a positive integer", ErrInvalidParam)
	}
	if !expiry.After(now) {
		record(false, HistoryErrorInvalidParam, nil, nil)
		return Commitment{}, fmt.Errorf("%w: expiry must be after current time", ErrInvalidParam)
	}

	req, ok := s.requests[requestID]
	if !ok {
		return Commitment{}, fmt.Errorf("%w: request %q", ErrNotFound, requestID)
	}
	if _, ok := s.parts[partID]; !ok {
		record(false, HistoryErrorPartNotFound, nil, nil)
		return Commitment{}, fmt.Errorf("%w: part %q", ErrNotFound, partID)
	}
	elig, err := s.evaluateLocked(req, now)
	if err != nil {
		// 产品未登记：资格依据明确为空，不用合格替代缺失。
		record(false, HistoryErrorProductNotFound, nil, nil)
		return Commitment{}, err
	}

	// 库存核算前先按本次时刻确认该备件已到期的承诺。到期确认不可逆，之后
	// 即使传入更早时刻也不再计入占用。放在参数与引用校验之后：提前失败的
	// 非法或缺失引用调用不确认任何承诺。
	s.confirmPartExpiriesLocked(partID, now)

	// 库存依据：本次提交处理前的实物剩余、有效占用与可承诺数量，与库存
	// 查询共用同一份核算；在新增承诺落库之前取快照，本次新增占用不计入。
	stockBasis := s.stockAccountLocked(partID)

	if !elig.Eligible {
		record(false, HistoryErrorIneligible, elig, &stockBasis)
		return Commitment{}, fmt.Errorf("%w: %v", ErrIneligible, elig.Reasons)
	}

	if quantity > stockBasis.Committable {
		record(false, HistoryErrorInsufficientStock, elig, &stockBasis)
		return Commitment{}, fmt.Errorf("%w: need %d, committable %d", ErrInsufficientStock, quantity, stockBasis.Committable)
	}

	c := &Commitment{
		ID:        commitID,
		RequestID: requestID,
		PartID:    partID,
		Quantity:  quantity,
		Expiry:    expiry,
	}
	// 成功记录、承诺与首次结果快照在同一把锁内同时落库，查询不会看到只占用库存
	// 却没有成功记录的中间状态；快照独立于活动承诺，之后的使用、取消或到期不
	// 会改变原样重试取回的值。
	s.commitments[commitID] = c
	s.firstResults[commitID] = *c
	record(true, "", elig, &stockBasis)
	return *c, nil
}

// Use 使用一笔承诺，数量为正整数，分批扣减该承诺未用数量和剩余实物库存。
// 数量超过未用数量时整次失败，不改变任何记录。
//
// 使用编号全局唯一：相同编号且相同内容的重试返回首次成功结果，不再次扣减，
// 也不借本次时刻确认任何承诺到期；编号一旦已有成功记录，后续提交的承诺编号或
// 数量与首次成功内容不同即返回 ErrConflict——即使新内容本身非法（空承诺编号、
// 指向不存在的承诺、数量为零或负数、超过承诺余量），或新指定的承诺已取消或
// 到期，也一律按编号冲突处理：不扣减实物库存、不改变任何承诺的已用数量、不
// 释放占用，也不借本次时刻确认原承诺或新承诺到期，更不会用新内容覆盖原记录。
// 首次成功与编号绑定在同一临界区内原子完成：多个相同内容的并发提交全部成功并
// 返回同一份完整使用记录，但承诺累计已用数量与实物库存只随首次成功变化一次
// （恰好耗尽余量时其余提交仍取回首次结果，不会被当作新的超量使用）；首次成功
// 前两组不同内容并发抢占同一编号时，只有一份内容成为成功记录，与其相同的提交
// 全部取回该结果，另一组全部 ErrConflict，扣减量只对应胜出内容，落败承诺不变。
// 已经成功的使用在承诺取消或到期后原样重试，仍返回原结果，已确认到期的承诺
// 也不会因此重新开放。新使用（非重试）会按本次当前时刻确认这一笔承诺：已取消
// 或已确认到期，或本次时刻达到其到期时刻的，一律返回 ErrCommitmentClosed；到期
// 一经确认不可逆，之后即使传入更早时刻也仍被拒绝。尚无成功记录的编号按本次
// 参数处理：空编号、空承诺编号、非正数量返回 ErrInvalidParam，引用未知承诺返回
// ErrNotFound，这些提前失败不用本次时刻确认到期，也不占用编号，修正内容后仍可
// 提交。已全部使用的承诺不再接受新使用。
func (s *Store) Use(usageID, commitID string, quantity int, now time.Time) (Usage, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	// 已成功的编号优先按重复提交处理，优先于本次参数校验：沿用成功编号但把
	// 承诺编号改成空串或未知承诺、把数量改成零或负数等本身非法的内容，仍属于
	// 对已成功提交内容的改动，按 ErrConflict 处理，与普通非法输入区分。成功
	// 使用的编号必非空，因此空编号不会命中这里，继续走参数校验。
	if existing, ok := s.usages[usageID]; ok {
		if existing.CommitmentID != commitID || existing.Quantity != quantity {
			return Usage{}, fmt.Errorf("%w: usage id %q reused with different content", ErrConflict, usageID)
		}
		return *existing, nil
	}

	if usageID == "" || commitID == "" {
		return Usage{}, fmt.Errorf("%w: usage/commit id must not be empty", ErrInvalidParam)
	}
	if quantity <= 0 {
		return Usage{}, fmt.Errorf("%w: usage quantity must be a positive integer", ErrInvalidParam)
	}

	c, ok := s.commitments[commitID]
	if !ok {
		return Usage{}, fmt.Errorf("%w: commitment %q", ErrNotFound, commitID)
	}
	// 新使用判断：按本次时刻确认这一笔承诺是否到期。一经确认不可逆，之后
	// 即使传入更早时刻也一律关闭。已取消的承诺不确认到期，仍保持 canceled。
	s.confirmExpiryLocked(c, now)
	if c.Canceled {
		return Usage{}, fmt.Errorf("%w: commitment %q is canceled", ErrCommitmentClosed, commitID)
	}
	if c.Expired {
		return Usage{}, fmt.Errorf("%w: commitment %q expired at %v", ErrCommitmentClosed, commitID, c.Expiry)
	}
	if quantity > c.Quantity-c.Used {
		return Usage{}, fmt.Errorf("%w: need %d, unused %d", ErrUsageExceeded, quantity, c.Quantity-c.Used)
	}

	c.Used += quantity
	s.parts[c.PartID].Stock -= quantity
	u := &Usage{ID: usageID, CommitmentID: commitID, Quantity: quantity}
	s.usages[usageID] = u
	return *u, nil
}

// Cancel 取消承诺，只释放未用数量，不影响已扣减的实物库存。
// 重复取消不增加库存；承诺已到期时余量已自动失效，取消同样不产生变化。
// 取消后的承诺不能继续使用。
func (s *Store) Cancel(commitID string, now time.Time) (Commitment, error) {
	if commitID == "" {
		return Commitment{}, fmt.Errorf("%w: commit id must not be empty", ErrInvalidParam)
	}
	s.mu.Lock()
	defer s.mu.Unlock()

	c, ok := s.commitments[commitID]
	if !ok {
		return Commitment{}, fmt.Errorf("%w: commitment %q", ErrNotFound, commitID)
	}
	if !c.Canceled {
		c.Canceled = true
	}
	return *c, nil
}

package warranty

import (
	"fmt"
	"sort"
	"time"
)

// CommitmentDetail 是承诺的明细视图，已取消或已到期的记录仍可追查。
type CommitmentDetail struct {
	// CommitmentID 是承诺编号。
	CommitmentID string
	// RequestID 是关联请求编号。
	RequestID string
	// PartID 是备件编号。
	PartID string
	// OriginalQuantity 是原定承诺数量。
	OriginalQuantity int
	// UsedQuantity 是已用数量。
	UsedQuantity int
	// RemainingQuantity 是剩余未用数量。
	RemainingQuantity int
	// Expiry 是到期时刻。
	Expiry time.Time
	// Status 是在查询时刻的状态（active/canceled/expired）。
	Status CommitmentStatus
}

// PartStatus 是按备件查询的库存与占用视图。
type PartStatus struct {
	// PartID 是备件编号。
	PartID string
	// PhysicalRemaining 是剩余实物库存（初始库存扣除全部成功使用量）。
	PhysicalRemaining int
	// ActiveOccupied 是有效承诺的未用总量。
	ActiveOccupied int
	// Committable 是还可承诺数量，等于剩余实物库存扣除有效承诺未用总量。
	Committable int
	// Details 是该备件的全部承诺明细（含已取消、已到期），按承诺编号排序。
	Details []CommitmentDetail
}

// RequestView 是按请求查询的资格与承诺视图。
type RequestView struct {
	// Eligibility 是资格依据与拒绝原因。
	Eligibility *Eligibility
	// Commitments 是该请求关联的全部承诺明细（含已取消、已到期），按承诺编号排序。
	Commitments []CommitmentDetail
}

// toDetailLocked 生成承诺在指定时刻的明细。
func toDetailLocked(c *Commitment, now time.Time) CommitmentDetail {
	return CommitmentDetail{
		CommitmentID:      c.ID,
		RequestID:         c.RequestID,
		PartID:            c.PartID,
		OriginalQuantity:  c.Quantity,
		UsedQuantity:      c.Used,
		RemainingQuantity: c.Quantity - c.Used,
		Expiry:            c.Expiry,
		Status:            c.Status(now),
	}
}

// commitmentDetailsLocked 是两种查询入口共用的承诺明细处理规则：收集全部满足
// match 的承诺（含已取消、已到期、已全部使用的记录），按本次时刻生成明细，
// 并按承诺编号升序排序。按请求查询与按备件查询只传入不同的归属条件，过滤、
// 明细生成与排序规则不再分别维护。返回的明细是独立副本，与仓库记录互不影响。
func (s *Store) commitmentDetailsLocked(match func(*Commitment) bool, now time.Time) []CommitmentDetail {
	var details []CommitmentDetail
	for _, c := range s.commitments {
		if !match(c) {
			continue
		}
		details = append(details, toDetailLocked(c, now))
	}
	sort.Slice(details, func(i, j int) bool {
		return details[i].CommitmentID < details[j].CommitmentID
	})
	return details
}

// CommitmentUsages 返回指定承诺已成功使用的明细列表，按使用编号的字符串升序排列。
// 每条明细是现有使用记录的副本，含使用编号、承诺编号和本次数量；列表中数量之和
// 即该承诺的已用数量。只收录绑定到这笔承诺的成功记录：同一请求或同一种备件下
// 其他承诺的使用不混入；超量、编号冲突等失败提交不产生记录，也不会覆盖已有的
// 成功记录。承诺全部使用、取消或到期（含已确认到期）后成功记录仍然保留，取消或
// 到期释放的未用数量不计入本列表；查询已关闭的承诺同样成功返回。
//
// 查询是只读操作：不扣减实物库存、不释放占用、不按任何时刻确认到期，也不追加
// 预留处理历史。空承诺编号返回 ErrInvalidParam；非空但不存在的承诺返回
// ErrNotFound；承诺存在但尚无成功使用时返回空列表。返回的列表是独立副本，
// 调用方修改或增删其中的内容不影响仓库记录与后续查询。
func (s *Store) CommitmentUsages(commitID string) ([]Usage, error) {
	if commitID == "" {
		return nil, fmt.Errorf("%w: commit id must not be empty", ErrInvalidParam)
	}
	s.mu.Lock()
	defer s.mu.Unlock()

	if _, ok := s.commitments[commitID]; !ok {
		return nil, fmt.Errorf("%w: commitment %q", ErrNotFound, commitID)
	}
	usages := make([]Usage, 0)
	for _, u := range s.usages {
		if u.CommitmentID == commitID {
			usages = append(usages, *u)
		}
	}
	sort.Slice(usages, func(i, j int) bool {
		return usages[i].ID < usages[j].ID
	})
	return usages, nil
}

// RequestView 返回指定请求在当前时刻的资格依据、拒绝原因和关联承诺。
// 查询会按本次当前时刻确认该请求下已到期的承诺：到期一经确认不可逆，之后
// 即使传入更早时刻，这些承诺也始终显示 expired、不再计入有效占用；到期时刻
// 前尚未确认失效的承诺仍按本次时刻显示 active。资格仍只按本次时刻判断，
// 不会用较大的历史时刻替换本次时刻。
func (s *Store) RequestView(requestID string, now time.Time) (*RequestView, error) {
	if requestID == "" {
		return nil, fmt.Errorf("%w: request id must not be empty", ErrInvalidParam)
	}
	s.mu.Lock()
	defer s.mu.Unlock()

	req, ok := s.requests[requestID]
	if !ok {
		return nil, fmt.Errorf("%w: request %q", ErrNotFound, requestID)
	}
	// 查询本身确认到期：本次时刻已达到到期时刻的关联承诺一经确认不可逆，
	// 之后即使传入更早时刻也不再计入占用、状态保持 expired。
	s.confirmRequestExpiriesLocked(requestID, now)
	elig, err := s.evaluateLocked(req, now)
	if err != nil {
		return nil, err
	}
	view := &RequestView{Eligibility: elig}
	view.Commitments = s.commitmentDetailsLocked(func(c *Commitment) bool {
		return c.RequestID == requestID
	}, now)
	return view, nil
}

// PartStatus 返回指定备件在当前时刻的实物剩余、有效占用、可承诺数量和占用明细。
// 查询会按本次当前时刻确认该备件下已到期的承诺：到期一经确认不可逆，只释放
// 未用占用、不增加实物库存，之后即使传入更早时刻，这些承诺也不再计入有效占用
// （可承诺数量不回落），明细持续显示 expired；已取消的记录仍显示 canceled。
func (s *Store) PartStatus(partID string, now time.Time) (*PartStatus, error) {
	if partID == "" {
		return nil, fmt.Errorf("%w: part id must not be empty", ErrInvalidParam)
	}
	s.mu.Lock()
	defer s.mu.Unlock()

	if _, ok := s.parts[partID]; !ok {
		return nil, fmt.Errorf("%w: part %q", ErrNotFound, partID)
	}
	// 查询本身确认到期：本次时刻已达到到期时刻的该备件承诺一经确认不可
	// 逆，之后即使传入更早时刻也不再计入占用。
	s.confirmPartExpiriesLocked(partID, now)
	// 实物剩余、有效占用与可承诺数量与新预留的库存核算共用同一条规则：
	// 占用只看持久状态，取消或已确认到期的承诺不占数量，不随本次时刻回退。
	account := s.stockAccountLocked(partID)
	view := &PartStatus{
		PartID:            partID,
		PhysicalRemaining: account.PhysicalRemaining,
		ActiveOccupied:    account.ActiveOccupied,
		Committable:       account.Committable,
	}
	view.Details = s.commitmentDetailsLocked(func(c *Commitment) bool {
		return c.PartID == partID
	}, now)
	return view, nil
}

package warranty

import "errors"

// 本包使用的错误。调用方可以用 errors.Is 判断具体失败原因。
var (
	// ErrDuplicateID 表示登记时使用了已存在的编号，原记录保留。
	ErrDuplicateID = errors.New("warranty: duplicate id")
	// ErrNotFound 表示引用的产品、备件、请求或承诺不存在。
	ErrNotFound = errors.New("warranty: not found")
	// ErrInvalidParam 表示入参不合法（如非正整数数量、缺少故障代码）。
	ErrInvalidParam = errors.New("warranty: invalid parameter")
	// ErrConflict 表示同一编号被重复用于不同内容。
	ErrConflict = errors.New("warranty: conflict")
	// ErrIneligible 表示请求在当次时刻不满足保修资格。
	ErrIneligible = errors.New("warranty: request is not eligible")
	// ErrInsufficientStock 表示可承诺数量不足。
	ErrInsufficientStock = errors.New("warranty: insufficient committable stock")
	// ErrCommitmentClosed 表示承诺已取消或已到期，不能继续使用。
	ErrCommitmentClosed = errors.New("warranty: commitment is no longer active")
	// ErrUsageExceeded 表示本次使用数量超过该承诺的未用数量，整次失败。
	ErrUsageExceeded = errors.New("warranty: usage exceeds unused quantity")
)

